import json
def transform(g):
    g=[row[:] for row in g]; H,W=len(g),len(g[0])
    fill=2; mark=1
    cells=[(r,c) for r in range(H) for c in range(W) if g[r][c]==fill]
    r0=min(r for r,c in cells); r1=max(r for r,c in cells)
    c0=min(c for r,c in cells); c1=max(c for r,c in cells)
    def setv(r,c):
        if g[r][c]==0: g[r][c]=fill
    for r in range(r0,r1+1):
        row=g[r]
        has=lambda side: any(row[c]==mark and (c<c0 if side=='L' else c>c1) for c in range(W))
        L,R=has('L'),has('R')
        if not L and not R:
            for c in range(W): setv(r,c)
        else:
            if not L:  # markers left -> fill right side
                for c in range(c1+1,W): setv(r,c)
            if not R:
                for c in range(0,c0): setv(r,c)
    for c in range(c0,c1+1):
        col=[g[r][c] for r in range(H)]
        hasU=any(col[r]==mark for r in range(0,r0))
        hasD=any(col[r]==mark for r in range(r1+1,H))
        if not hasU and not hasD:
            for r in range(H): setv(r,c)
        else:
            if not hasU:
                for r in range(0,r0): setv(r,c)
            if not hasD:
                for r in range(r1+1,H): setv(r,c)
    return g

